// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 warpTime, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0));
        warpTime = bound(warpTime, 1, 2 ** 250);
        unlockTime = bound(unlockTime, 0, 2 ** 250);
        vm.warp(warpTime);

        uint256 value = 1 ether;
        vm.deal(actor, value);
        vm.prank(actor);
        c.Put{value: value}(unlockTime);

        (uint256 storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime >= warpTime);
    }
}
